class RpcError extends Error{constructor(message,code=0){super(message);this.code=code;}}
function rpcMessage(code,object,method){
  if(code===6)return object==='blaze'&&method==='status'?'Your EasyMode session expired. Sign in again.':`Permission denied for ${object}.${method}. EasyMode files/ACL may be mismatched.`;
  if(code===3)return `EasyMode method ${object}.${method} is missing from the running backend. Restart rpcd or reinstall the matched EasyMode package.`;
  if(code===4)return `EasyMode object ${object} is not available on the router.`;
  if(code===7)return `Router request timed out: ${object}.${method}`;
  if(code===8)return `Router does not support ${object}.${method}.`;
  return `Router request failed (${code||'unknown'}): ${object}.${method}`;
}
function methodMissing(e){return e instanceof RpcError&&(e.code===3||e.code===4);}
function backendMismatch(){return state?.rpc_api!==RPC_API;}
async function rpc(object,method,args={},token=sid){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);
  try{
    const response=await fetch('/ubus',{method:'POST',headers:{'Content-Type':'application/json','Cache-Control':'no-store'},cache:'no-store',signal:controller.signal,body:JSON.stringify({jsonrpc:'2.0',id:requestId++,method:'call',params:[token||'00000000000000000000000000000000',object,method,args]})});
    if(!response.ok)throw new RpcError(`Router returned HTTP ${response.status}.`);
    let r;try{r=await response.json();}catch{throw new RpcError('Router returned an invalid RPC response.');}
    const code=Number(r?.result?.[0]??(r.error?-1:0));
    if(r.error||code!==0){
      if(code===6&&object==='blaze'&&method==='status'&&token!==''&&sid)logout('Your session expired. Sign in again.');
      throw new RpcError(rpcMessage(code,object,method),code);
    }
    return r.result?.[1]||{};
  }catch(e){if(e?.name==='AbortError')throw new RpcError('The router did not answer in time.');throw e;}finally{clearTimeout(timer);}
}
function toast(s){const e=$('#toast');if(!e)return;e.textContent=s;e.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.hidden=true,9000);}
async function messageResult(r){const deadline=Date.now()+75000;while(r?.pending){if(Date.now()>deadline)throw Error('The modem has not returned a result yet. Do not automatically resend.');await new Promise(resolve=>setTimeout(resolve,700));r=await rpc('blaze','message_status',{id:r.id});}if(r?.ok===false)throw Error(r.error||r.message||'Modem operation failed');return r||{};}
async function action(name,p={}){
  if(busy)throw Error('Wait for the current operation to finish.');busy=true;
  try{
    if((name==='sms_send'||name==='ussd')&&inboxPending)await inboxPending;
    const r=await messageResult(await rpc('blaze','action',{action:name,payload:JSON.stringify(p)}));
    if(r.ok===false)throw Error(r.error||r.message||'Operation failed');
    toast(r.message||'Settings saved.');
    if(name==='bands')modemCache=null;
    await refresh(false);return r;
  }catch(e){toast(e.message);throw e;}finally{busy=false;}
}
