function theme(){const s=state.config?.settings||{};document.documentElement.dataset.theme=s.theme||'dark';document.documentElement.style.setProperty('--accent',/^#[0-9a-f]{6}$/i.test(s.accent)?s.accent:'#24b8dc');}
