function radioTech(r){const mode=String(r.mode||'').trim();if(mode&&mode!=='-')return mode;if(r.ca)return'LTE+ / carrier aggregation';return activeCarriers(r).length?'4G LTE':'Waiting for modem';}
function activeBandText(r){const a=activeCarriers(r);return a.length?a.map(c=>`${String(r.mode||'').toUpperCase().includes('NR')?'n':'B'}${c.band}${Number(c.width)>0?' · '+c.width+' MHz':''}`).join(' + '):'—';}
