 const ranges={rsrp:[-140,-80],rsrq:[-20,-3],sinr:[-10,30],rssi:[-113,-51],csq:[0,31]},r=ranges[metricName];if(value==null||!r)return {pct:0,label:'Unavailable'};const pct=Math.max(0,Math.min(100,100*(Number(value)-r[0])/(r[1]-r[0])));return {pct,label:pct>=75?'Excellent':pct>=55?'Good':pct>=35?'Fair':'Weak'};
