async function runNettest(kind){if(nettestBusy)throw Error('A network test is already running.');nettestBusy=true;const buttons=['#run-ping','#run-diag','#run-speed'].map(s=>$(s)).filter(Boolean);buttons.forEach(b=>b.disabled=true);const result=$('#diag-result');if(result){result.hidden=false;result.textContent='Running '+kind+' test…';}try{const source=$('#diag-source')?.value||'auto',target=$('#diag-target')?.value||'1.1.1.1',url=$('#speed-url')?.value||'https://speed.cloudflare.com/__down?bytes=25000000';let r=await rpc('blaze','nettest_start',{kind,source,target,url});if(r.ok===false)throw Error(r.error||r.message);r=await waitNettest(r);if(result?.isConnected)result.textContent=(r.message||'')+(r.mbps?`\n\nDownload: ${r.mbps} Mbps\nTransferred: ${(Number(r.bytes||0)/1e6).toFixed(1)} MB in ${r.seconds}s\nHTTP: ${r.http_code} · ${r.remote_ip||''}`:'')+(r.raw?'\n\n'+r.raw:'');if(!r.ok)throw Error(r.message||'Network test failed.');}catch(e){if(result?.isConnected)result.textContent='Test failed: '+e.message;throw e;}finally{nettestBusy=false;buttons.forEach(b=>b.disabled=false);}}
