  frame(`<h2>Cellular signal history</h2><p class="muted">One read-only sample every two minutes. The last 24 hours stay in router memory; resetting or rebooting clears the chart.</p><div class="quality-summary">${detail('Current RSRP',radio.rsrp==null?'—':radio.rsrp+' dBm')}${detail('Current RSRQ',radio.rsrq==null?'—':radio.rsrq+' dB')}${detail('Current SINR',radio.sinr==null?'—':radio.sinr+' dB')}${detail('Current RSSI',radio.rssi==null?'—':radio.rssi+' dBm')}</div><h3>Recent RSRP</h3><div class="quality-bars signal-bars" role="img" aria-label="Recent RSRP signal strength; taller bars mean stronger signal">${bars||'<span class="muted small">Collecting samples…</span>'}</div><p class="muted small">Each bar is a two-minute sample. The chart uses only the modem cache, so it does not interrupt SMS or other radio operations.</p><div class="client-table-scroll"><table><thead><tr><th>TIME</th><th>RSRP</th><th>RSRQ</th><th>SINR</th><th>RSSI</th></tr></thead><tbody>${samples.slice(-12).reverse().map(x=>`<tr><td>${esc(new Date(Number(x.time)*1000).toLocaleString())}</td><td>${Number(x.rsrp)} dBm</td><td>${Number(x.rsrq)} dB</td><td>${Number(x.sinr)} dB</td><td>${Number(x.rssi)} dBm</td></tr>`).join('')||'<tr><td colspan="5">Waiting for the first signal sample.</td></tr>'}</tbody></table></div>`);
