function bandSection(rat,title,desc,group){if(!group.supported.length)return'';return `<section class="band-group"><div class="row band-group-head"><div><h3>${esc(title)}</h3><p class="muted small">${esc(desc)}</p></div><div class="mini-actions"><button class="ghost small" data-band-all="${rat}">All</button><button class="ghost small" data-band-none="${rat}">Clear</button></div></div><div class="bands">${group.supported.map(x=>bandBox(x,rat,group.enabled)).join('')}</div><button class="primary" data-band-apply="${rat}">Apply ${esc(title)} selection</button></section>`;}
function bindBandHelpers(){
  document.querySelectorAll('[data-band-all]').forEach(b=>b.onclick=()=>document.querySelectorAll(`[data-band][data-rat="${b.dataset.bandAll}"]`).forEach(x=>x.checked=true));
  document.querySelectorAll('[data-band-none]').forEach(b=>b.onclick=()=>document.querySelectorAll(`[data-band][data-rat="${b.dataset.bandNone}"]`).forEach(x=>x.checked=false));
  document.querySelectorAll('[data-band-apply]').forEach(b=>b.onclick=async()=>{try{await applyBands(b.dataset.bandApply);}catch(e){toast(e.message);}});
}
async function applyBands(rat){
  const bands=[...document.querySelectorAll(`[data-band][data-rat="${rat}"]:checked`)].map(e=>Number(e.value)).filter(Boolean);
  if(!bands.length)throw Error('Choose at least one supported band.');
  const test=$('#speed-trial')?.checked||false,requireCA=$('#require-ca')?.checked||false;
  await action('bands',{rat,bands:bands.join(' '),test,requireCA});
}
